//! Minimal JSON reading for the differential test vectors.
//!
//! The vector files have a known, flat shape and are generated by this crate's
//! own scripts, so pulling in serde purely for tests would add dependencies
//! without adding confidence. These helpers scan strings and panic loudly on
//! anything unexpected.

#![allow(dead_code)]

use num_bigint::BigUint;

/// The text of the array named `key`, without its enclosing brackets.
pub fn array_body(src: &str, key: &str) -> String {
    let needle = format!("\"{key}\":");
    let start = src.find(&needle).unwrap_or_else(|| panic!("no key {key}"));
    let open = src[start..].find('[').expect("array open") + start;
    let mut depth = 0usize;
    for (i, c) in src[open..].char_indices() {
        match c {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 {
                    return src[open + 1..open + i].to_string();
                }
            }
            _ => {}
        }
    }
    panic!("unterminated array {key}");
}

/// Split a JSON array body into its top-level `{...}` objects.
pub fn objects(body: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth = 0usize;
    let mut start = 0usize;
    for (i, c) in body.char_indices() {
        match c {
            '{' => {
                if depth == 0 {
                    start = i;
                }
                depth += 1;
            }
            '}' => {
                depth -= 1;
                if depth == 0 {
                    out.push(body[start..=i].to_string());
                }
            }
            _ => {}
        }
    }
    out
}

/// The string value of `key` in a flat object. JSON `\uXXXX` is not handled,
/// because the generators emit raw UTF-8.
pub fn string_field(obj: &str, key: &str) -> String {
    let needle = format!("\"{key}\":");
    let at = obj
        .find(&needle)
        .unwrap_or_else(|| panic!("no field {key} in {obj}"));
    let rest = &obj[at + needle.len()..];
    let open = rest.find('"').expect("string open");
    let after = &rest[open + 1..];
    // Honour backslash escapes so a value containing `\"` is read whole.
    let mut end = 0usize;
    let bytes = after.as_bytes();
    while end < bytes.len() {
        match bytes[end] {
            b'\\' => end += 2,
            b'"' => break,
            _ => end += 1,
        }
    }
    after[..end].replace("\\\"", "\"").replace("\\\\", "\\")
}

/// The integer value of `key` in a flat object.
pub fn usize_field(obj: &str, key: &str) -> usize {
    let needle = format!("\"{key}\":");
    let at = obj
        .find(&needle)
        .unwrap_or_else(|| panic!("no field {key} in {obj}"));
    obj[at + needle.len()..]
        .trim_start()
        .chars()
        .take_while(|c| c.is_ascii_digit())
        .collect::<String>()
        .parse()
        .unwrap_or_else(|_| panic!("field {key} is not an integer"))
}

/// The boolean value of `key` in a flat object.
pub fn bool_field(obj: &str, key: &str) -> bool {
    let needle = format!("\"{key}\":");
    let at = obj
        .find(&needle)
        .unwrap_or_else(|| panic!("no field {key} in {obj}"));
    let rest = obj[at + needle.len()..].trim_start();
    if rest.starts_with("true") {
        true
    } else if rest.starts_with("false") {
        false
    } else {
        panic!("field {key} is not a boolean")
    }
}

/// Decode lowercase hex into bytes.
pub fn unhex(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap_or_else(|e| panic!("bad hex {s:?}: {e}"))
}

/// Decode a 32-byte hex string.
pub fn unhex32(s: &str) -> [u8; 32] {
    unhex(s).try_into().expect("expected 32 bytes")
}

/// Parse an even-length lowercase big-endian hex integer, as `int_hex` emits.
pub fn big(s: &str) -> BigUint {
    BigUint::parse_bytes(s.as_bytes(), 16).unwrap_or_else(|| panic!("bad bigint hex {s:?}"))
}
